 for(const row of states){delete row._area;assert(row.d&&row.c.every(Number.isFinite),'Invalid target '+row.n);assert(!/NaN|Infinity/.test(row.d),'Invalid path '+row.n);assert(row.c[0]>=0&&row.c[0]<=definition.width&&row.c[1]>=0&&row.c[1]<=definition.height,'Target outside viewport '+row.n);}
 assert.equal(new Set(states.map(row=>row.n)).size,states.length,'Duplicate target names');
